def read_account(account_id: int, request: Request):
    account = current(request)
    conn = request.app.state.conn
    row = conn.execute("SELECT * FROM accounts WHERE id = ?", (account_id,)).fetchone()
    if row is None:
        fail(404, "not found")
    return account_json(row, include_recovery=int(account["id"]) == int(row["id"]))

def may_view_device(conn, caller_id, device_id):
    device = conn.execute("SELECT * FROM devices WHERE id = ?", (device_id,)).fetchone()
    if device is None:
        return False
    if int(device["owner_account_id"]) == int(caller_id):
        return True
    share = conn.execute(
        "SELECT id FROM device_shares WHERE device_id = ? AND account_id = ?",
        (device_id, caller_id),
    ).fetchone()
    return share is not None

def transfer_device(conn, device_id, to_account_id):
    conn.execute("UPDATE devices SET owner_account_id = ? WHERE id = ?", (to_account_id, device_id))
    conn.execute(
        "UPDATE device_bindings SET released_at = ? WHERE device_id = ? AND released_at IS NULL",
        (now(), device_id),
    )
    conn.execute(
        "INSERT INTO device_bindings (device_id, account_id, bound_at, released_at) VALUES (?, ?, ?, NULL)",
        (device_id, to_account_id, now()),
    )
    conn.commit()

def update_device(device_id: int, body: DeviceUpdate, request: Request):
    account = current(request)
    label = body.label.strip()
    if not label:
        fail(400, "invalid device")
    conn = request.app.state.conn
    row = conn.execute("SELECT * FROM devices WHERE id = ?", (device_id,)).fetchone()
    if row is None:
        fail(404, "not found")
    if int(row["owner_account_id"]) != int(account["id"]):
        fail(403, "forbidden")
    conn.execute("UPDATE devices SET label = ? WHERE id = ?", (label, device_id))
    conn.commit()

def device_notes_for(conn, caller_id, device_id):
    if not may_view_device(conn, caller_id, device_id):
        return None
    return conn.execute(
        "SELECT * FROM device_notes WHERE device_id = ? AND author_account_id = ? ORDER BY id",
        (device_id, caller_id),
    ).fetchall()

