def account_for_token(conn, token):
    row = conn.execute("SELECT account_id FROM sessions WHERE token = ?", (token,)).fetchone()
    if row is None:
        return None
    account = conn.execute("SELECT * FROM accounts WHERE id = ?", (row["account_id"],)).fetchone()
    if account is None:
        return None
    if account["status"] != "active" or account["merged_into_id"] is not None:
        return None
    return account

